cat > src/loyalty/domain/points.ts <<'EOF'
/** Loyalty domain: base points earned for an order subtotal (1 point per whole euro). */
export function basePoints(subtotalCents: number): number {
  return Math.floor(subtotalCents / 100);
}

/** Points awarded for an order: floor(base points x campaign multiplier). */
export function awardedPoints(subtotalCents: number, multiplier: number): number {
  return Math.floor(basePoints(subtotalCents) * multiplier);
}
EOF

cat > src/loyalty/application/award-points.ts <<'EOF'
import { awardedPoints } from "../domain/points.ts";
import { activeMultiplier } from "../integration/campaigns.ts";
import type { PointsLedger } from "../integration/points-ledger.ts";

/** Use case: award loyalty points for an order and credit them to the customer's ledger. */
export function awardOrderPoints(ledger: PointsLedger, customerId: string, subtotalCents: number): number {
  const points = awardedPoints(subtotalCents, activeMultiplier());
  ledger.credit(customerId, points);
  return points;
}
EOF
